import "./App.css";

function App() {
    return (
        <div className="App">
            <h1>Trading Journal</h1>
            <Balances />
            <TradeForm />
        </div>
    );
}

function Balances() {
    return (
        <div>
            <label>Account Balance</label>
            <input type="text" disabled />
        </div>
    );
}

function TradeForm() {
    return (
        <form className="form">
            <div>
                <label>Stock</label>
                <input type="text" />
            </div>
            <div>
                <label>Shares</label>
                <input type="text" />
            </div>
            <div>
                <label>Price</label>
                <input type="text" />
            </div>
            <div>
                <label>Total</label>
                <input type="text" disabled />
            </div>
            <button>Buy</button>
            <button>Sell</button>
        </form>
    );
}

function DepositAndWithdrawalForm() {
    return (
        <form className="form">
            <div>
                <label>Amount</label>
                <input type="text" />
                <button>Deposit</button>
                <button>Withdraw</button>
            </div>
        </form>
    );
}

function TransactionTable() {}

function TradesTable() {}

export default App;
